//! Durable operational requests/results only. No financial tables are written.
use crate::{Store,StoreError,identity::{self,Permission},kitchen::Action};
use rusqlite::{Transaction,TransactionBehavior,OptionalExtension,params};use serde::{Serialize,Deserialize};use serde_json::{Value,json};
#[derive(Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Request{pub version:u32,pub hub_id:String,pub business_id:String,pub actor_id:String,pub operation_id:String,pub ticket_id:String,pub expected_revision:i64,pub target_actor_id:String}
pub(crate) fn migrate(tx:&Transaction<'_>)->Result<(),StoreError>{tx.execute_batch(include_str!("assignment_recovery-schema.sql"))?;Ok(())}
impl Store{
 fn assignment_scope(&self,r:&Request)->Result<(),StoreError>{let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&self.0,s,Permission::KitchenView)?;if r.version!=1||r.expected_revision<1||![&r.operation_id,&r.ticket_id,&r.target_actor_id].iter().all(|v|crate::billing::valid_id(v)){return Err(StoreError::InvalidDraft);}if r.actor_id!=s.actor_id||r.business_id!=s.scope.business_id||self.hub_identity()?["hubId"]!=r.hub_id{return Err(StoreError::WorkspaceMismatch);}Ok(())}
 pub(crate) fn assignment_prepare(&mut self,id:String,ticket:String,revision:i64,target:String)->Result<Value,StoreError>{
 let s=self.1.as_ref().ok_or(StoreError::Locked)?;let r=Request{version:1,hub_id:self.hub_identity()?["hubId"].as_str().ok_or(StoreError::InvalidIdentity)?.into(),business_id:s.scope.business_id.clone(),actor_id:s.actor_id.clone(),operation_id:id,ticket_id:ticket,expected_revision:revision,target_actor_id:target};self.assignment_scope(&r)?;let raw=serde_json::to_string(&r)?;let tx=self.0.transaction_with_behavior(TransactionBehavior::Immediate)?;identity::verify(&tx,s,Permission::KitchenSupervise)?;
 if tx.query_row("SELECT EXISTS(SELECT 1 FROM local_kitchen_assignment_ops WHERE id=?1 AND NOT(actor_id=?2 AND generation=?3 AND device='desktop'))",params![r.operation_id,s.actor_id,s.generation],|q|q.get::<_,bool>(0))?{return Err(StoreError::OperationConflict);}
 let old:Option<String>=tx.query_row("SELECT request FROM local_kitchen_assignment_ops WHERE id=?1 AND actor_id=?2 AND generation=?3 AND device='desktop'",params![r.operation_id,s.actor_id,s.generation],|q|q.get(0)).optional()?;if let Some(old)=old{if old!=raw{return Err(StoreError::OperationConflict);}}else{if tx.query_row("SELECT EXISTS(SELECT 1 FROM local_kitchen_staff_events WHERE id=?1) OR EXISTS(SELECT 1 FROM local_hub_operations WHERE id=?1) OR EXISTS(SELECT 1 FROM local_restaurant_events WHERE operation_id=?1)",[&r.operation_id],|q|q.get::<_,bool>(0))?{return Err(StoreError::OperationConflict);}if tx.query_row("SELECT EXISTS(SELECT 1 FROM local_kitchen_assignment_ops WHERE actor_id=?1 AND generation=?2 AND device='desktop' AND acknowledged=0)",params![s.actor_id,s.generation],|q|q.get::<_,bool>(0))?{return Err(StoreError::Conflict);}tx.execute("INSERT INTO local_kitchen_assignment_ops(id,actor_id,generation,device,request,state) VALUES(?1,?2,?3,'desktop',?4,'prepared')",params![r.operation_id,s.actor_id,s.generation,raw])?;}tx.commit()?;self.assignment_pending()
 }
 pub(crate) fn assignment_pending(&self)->Result<Value,StoreError>{let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&self.0,s,Permission::KitchenView)?;let row:Option<(String,String,Option<String>)>=self.0.query_row("SELECT request,state,result FROM local_kitchen_assignment_ops WHERE actor_id=?1 AND generation=?2 AND device='desktop' AND acknowledged=0",params![s.actor_id,s.generation],|q|Ok((q.get(0)?,q.get(1)?,q.get(2)?))).optional()?;Ok(match row{Some((request,state,result))=>json!({"request":serde_json::from_str::<Value>(&request)?,"state":state,"result":result.map(|v|serde_json::from_str::<Value>(&v)).transpose()?}),None=>Value::Null})}
 pub(crate) fn assignment_ack(&mut self,id:String)->Result<Value,StoreError>{let tx=self.0.transaction_with_behavior(TransactionBehavior::Immediate)?;let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&tx,s,Permission::KitchenView)?;if tx.execute("UPDATE local_kitchen_assignment_ops SET acknowledged=1 WHERE id=?1 AND actor_id=?2 AND generation=?3 AND device='desktop' AND state IN('accepted','refused')",params![id,s.actor_id,s.generation])?!=1{return Err(StoreError::Conflict);}tx.commit()?;Ok(Value::Null)}
 pub(crate) fn assignment_resume(&mut self)->Result<Value,StoreError>{let pending=self.assignment_pending()?;if pending.is_null(){return Err(StoreError::InvalidDraft);}let r:Request=serde_json::from_value(pending["request"].clone())?;self.assignment_execute("desktop",r,None)?;self.assignment_pending()}
 pub(crate) fn assignment_status(&self,device:&str,id:&str)->Result<Value,StoreError>{let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&self.0,s,Permission::KitchenView)?;let row:Option<String>=self.0.query_row("SELECT result FROM local_kitchen_assignment_ops WHERE id=?1 AND actor_id=?2 AND generation=?3 AND device=?4 AND state IN('accepted','refused')",params![id,s.actor_id,s.generation,device],|q|q.get(0)).optional()?;Ok(row.map(|v|serde_json::from_str(&v)).transpose()?.unwrap_or(json!({"status":"not_found"})))}
 pub(crate) fn assignment_execute(&mut self,device:&str,r:Request,token:Option<&str>)->Result<Value,StoreError>{
 self.assignment_scope(&r)?;let slot=if token.is_some(){format!("lan:{device}")}else{"desktop".into()};let raw=serde_json::to_string(&r)?;let tx=self.0.transaction_with_behavior(TransactionBehavior::Immediate)?;let s=self.1.as_ref().ok_or(StoreError::Locked)?;identity::verify(&tx,s,Permission::KitchenSupervise)?;
 if let Some(token)=token{if !tx.query_row("SELECT EXISTS(SELECT 1 FROM local_hub_sessions h JOIN local_hub_devices d ON d.id=h.device_id WHERE h.token_hash=?1 AND h.device_id=?2 AND h.actor_id=?3 AND h.actor_revision=?4 AND h.expires>strftime('%s','now') AND d.expires>strftime('%s','now') AND d.state='approved' AND d.actor_id=h.actor_id AND d.revision=h.device_revision AND d.generation=h.generation AND h.generation=?5)",params![crate::hub::hash(token),device,s.actor_id,s.revision,s.generation],|q|q.get::<_,bool>(0))?{return Err(StoreError::Forbidden);}}
 let old:Option<(String,String,String,String,Option<String>)>=tx.query_row("SELECT actor_id,generation,device,request,result FROM local_kitchen_assignment_ops WHERE id=?1",[&r.operation_id],|q|Ok((q.get(0)?,q.get(1)?,q.get(2)?,q.get(3)?,q.get(4)?))).optional()?;if let Some((actor,generation,prior_device,request,result))=old{if actor!=s.actor_id||generation!=s.generation||prior_device!=slot||request!=raw{return Err(StoreError::OperationConflict);}if let Some(result)=result{return Ok(serde_json::from_str(&result)?);}}else{tx.execute("INSERT INTO local_kitchen_assignment_ops(id,actor_id,generation,device,request,state) VALUES(?1,?2,?3,?4,?5,'unknown')",params![r.operation_id,s.actor_id,s.generation,slot,raw])?;}
 if tx.query_row("SELECT EXISTS(SELECT 1 FROM local_hub_operations WHERE id=?1) OR EXISTS(SELECT 1 FROM local_restaurant_events WHERE operation_id=?1)",[&r.operation_id],|q|q.get::<_,bool>(0))?{return Err(StoreError::OperationConflict);}
 if tx.query_row("SELECT EXISTS(SELECT 1 FROM local_kitchen_staff_events WHERE id=?1)",[&r.operation_id],|q|q.get::<_,bool>(0))?{return Err(StoreError::OperationConflict);}
 tx.execute_batch("SAVEPOINT assign_ticket")?;
 let result=match crate::kitchen_staff::assign_ticket(&tx,&self.1,&r.ticket_id,r.expected_revision,&r.target_actor_id){Ok(value)=>{let a=Action::AssignTicket{operation_id:r.operation_id.clone(),ticket_id:r.ticket_id.clone(),expected_revision:r.expected_revision,actor_id:r.target_actor_id.clone()};tx.execute("INSERT INTO local_kitchen_staff_events(id,actor_id,ticket_id,request,result) VALUES(?1,?2,?3,?4,?5)",params![r.operation_id,s.actor_id,r.ticket_id,serde_json::to_string(&a)?,value.to_string()])?;json!({"status":"accepted","kind":"kitchen_assignment","operationId":r.operation_id,"ticketId":r.ticket_id,"revision":value["revision"],"actorId":value["actorId"]})},Err(e)=>{tx.execute_batch("ROLLBACK TO assign_ticket")?;let reason=match e{StoreError::Conflict=>"revision_conflict",StoreError::Forbidden=>"employee_unavailable",StoreError::WorkspaceMismatch=>"wrong_shop",StoreError::InvalidIdentity|StoreError::InvalidDraft=>"invalid_assignment",_=>return Err(e)};let revision:Option<i64>=tx.query_row("SELECT revision FROM local_restaurant_tickets WHERE id=?1",[&r.ticket_id],|q|q.get(0)).optional()?;let actor:Option<String>=tx.query_row("SELECT actor_id FROM local_kitchen_ticket_staff WHERE ticket_id=?1",[&r.ticket_id],|q|q.get(0)).optional()?;json!({"status":"refused","kind":"kitchen_assignment","operationId":r.operation_id,"ticketId":r.ticket_id,"reason":reason,"revision":revision,"actorId":actor})}};
 tx.execute_batch("RELEASE assign_ticket")?;tx.execute("UPDATE local_kitchen_assignment_ops SET state=?1,result=?2 WHERE id=?3",params![result["status"].as_str().ok_or(StoreError::InvalidDraft)?,result.to_string(),r.operation_id])?;identity::guard(&tx,&self.1,Permission::KitchenSupervise,"kitchen.assignment_result",Some(&r.operation_id))?;if token.is_some(){tx.execute("UPDATE local_hub_devices SET last_seen=strftime('%s','now') WHERE id=?1",[device])?;}tx.commit()?;Ok(result)
 }
}
#[cfg(test)]mod tests{
 use super::*;use crate::access::Workspace;
 const KEY:&str="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";const PASSWORD:&str="Synthetic assignment recovery password";
 fn ticket(w:&Workspace){w.store_for_test().0.execute("INSERT INTO local_restaurant_orders(id,kind,state,revision) VALUES('order','takeaway','open',1)",[]).unwrap();w.store_for_test().0.execute("INSERT INTO local_restaurant_tickets VALUES('kot','order','[]','pending',1)",[]).unwrap();}
 #[test]fn desktop_prepared_assignment_survives_reopen_and_replays_once(){let dir=tempfile::tempdir().unwrap();let path=dir.path().join("assignment.db");let mut w=Workspace::new(Store::open(&path,KEY).unwrap());w.setup(PASSWORD).unwrap();ticket(&w);let actor=w.local_session().unwrap().principal.id;w.kitchen_action(Action::PrepareAssignment{operation_id:"op".into(),ticket_id:"kot".into(),expected_revision:1,actor_id:actor}).unwrap();drop(w);
 let mut w=Workspace::new(Store::open(&path,KEY).unwrap());w.login("owner",PASSWORD).unwrap();assert_eq!(w.kitchen_action(Action::PendingAssignment).unwrap()["state"],"prepared");let result=w.kitchen_action(Action::ResumeAssignment).unwrap();assert_eq!(result["state"],"accepted");assert_eq!(w.kitchen_action(Action::ResumeAssignment).unwrap(),result);assert_eq!(w.store_for_test().0.query_row("SELECT revision FROM local_restaurant_tickets WHERE id='kot'",[],|q|q.get::<_,i64>(0)).unwrap(),2);assert_eq!(w.store_for_test().0.query_row("SELECT count(*) FROM local_kitchen_staff_events",[],|q|q.get::<_,i64>(0)).unwrap(),1);w.kitchen_action(Action::AcknowledgeAssignment{operation_id:"op".into()}).unwrap();assert!(w.kitchen_action(Action::PendingAssignment).unwrap().is_null());}
 #[test]fn stale_assignment_is_durable_refusal_without_financial_writes(){let mut w=Workspace::new(Store::open(std::path::Path::new(":memory:"),KEY).unwrap());w.setup(PASSWORD).unwrap();ticket(&w);let actor=w.local_session().unwrap().principal.id;w.kitchen_action(Action::PrepareAssignment{operation_id:"op".into(),ticket_id:"kot".into(),expected_revision:9,actor_id:actor}).unwrap();let result=w.kitchen_action(Action::ResumeAssignment).unwrap();assert_eq!(result["result"]["reason"],"revision_conflict");assert_eq!(w.kitchen_action(Action::ResumeAssignment).unwrap(),result);for table in ["local_invoices","local_billing_ledger","local_credit_entries","local_inventory_events"]{assert_eq!(w.store_for_test().0.query_row(&format!("SELECT count(*) FROM {table}"),[],|q|q.get::<_,i64>(0)).unwrap(),0);}}
}
